const listLadoVerificationOutcomes = `-- name: ListLadoVerificationOutcomes :many
SELECT execution_session_id, head_sha, outcome, reason
FROM lado_verifications
WHERE execution_session_id IN (/*SLICE:session_ids*/?)
  AND head_sha IN (/*SLICE:head_shas*/?)
`

type ListLadoVerificationOutcomesParams struct {
	SessionIds []string
	HeadShas   []string
}

type ListLadoVerificationOutcomesRow struct {
	ExecutionSessionID string
	HeadSha            string
	Outcome            string
	Reason             string
}

// The outcome and reason of the records of the given executions and heads.
// The caller keeps the (execution, head) pairs it asked for.
func (q *Queries) ListLadoVerificationOutcomes(ctx context.Context, arg ListLadoVerificationOutcomesParams) ([]ListLadoVerificationOutcomesRow, error) {
	query := listLadoVerificationOutcomes
	var queryParams []interface{}
	if len(arg.SessionIds) > 0 {
		for _, v := range arg.SessionIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:session_ids*/?", strings.Repeat(",?", len(arg.SessionIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:session_ids*/?", "NULL", 1)
	}
	if len(arg.HeadShas) > 0 {
		for _, v := range arg.HeadShas {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:head_shas*/?", strings.Repeat(",?", len(arg.HeadShas))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:head_shas*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListLadoVerificationOutcomesRow{}
	for rows.Next() {
		var i ListLadoVerificationOutcomesRow
		if err := rows.Scan(
			&i.ExecutionSessionID,
			&i.HeadSha,
			&i.Outcome,
			&i.Reason,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

