const upsertLadoVerification = `-- name: UpsertLadoVerification :exec
INSERT INTO lado_verifications (
    execution_session_id, head_sha, pr_url, outcome, reason, content_json, sha256, notified_json, protection_error,
    computed_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (execution_session_id, head_sha) DO UPDATE SET
    pr_url = excluded.pr_url,
    outcome = excluded.outcome,
    reason = excluded.reason,
    content_json = excluded.content_json,
    sha256 = excluded.sha256,
    notified_json = excluded.notified_json,
    protection_error = excluded.protection_error,
    computed_at = excluded.computed_at
`

type UpsertLadoVerificationParams struct {
	ExecutionSessionID string
	HeadSha            string
	PRURL              string
	Outcome            string
	Reason             string
	ContentJson        string
	Sha256             string
	NotifiedJson       string
	ProtectionError    string
	ComputedAt         time.Time
}

// One record per execution and head. Only a change of outcome, reason or
// sha256 publishes a change event (the update trigger's condition).
func (q *Queries) UpsertLadoVerification(ctx context.Context, arg UpsertLadoVerificationParams) error {
	_, err := q.db.ExecContext(ctx, upsertLadoVerification,
		arg.ExecutionSessionID,
		arg.HeadSha,
		arg.PRURL,
		arg.Outcome,
		arg.Reason,
		arg.ContentJson,
		arg.Sha256,
		arg.NotifiedJson,
		arg.ProtectionError,
		arg.ComputedAt,
	)
	return err
}
